// Onboarding answers: the shape the questions fill in, and the pure functions that turn it into
// the Robot a job runs on and the company facts the dashboard shows.

import type { ProjectFacts } from '../events'
import type { BomRow, Robot } from '../types'

export type YesNo = 'yes' | 'no' | 'unsure'

export interface Answers {
  company: string
  kind: 'company' | 'club'
  use_case: string
  sells_to_us_federal: YesNo
  deploy_countries: string[]
  uptime_critical: YesNo
  budget_usd: number | null
  need_by_days: number | null
  robot_name: string
  final_assembly_country: string
  mass_kg: number
  wheel_radius_mm: number
  n_drive_motors: number
  gear_ratio: number
  max_slope_deg: number
  v_max_mps: number
  accel_mps2: number
  bus_voltage_v: number
  envelope_mm: number
  efficiency: number
  crr: number
  safety_factor: number
  bom: BomRow[]
}

/** Drivetrain and product answers start at the demo robot's values. The BOM starts empty: the
 * user uploads theirs or picks the sample. */
export function defaultAnswers(demo: Robot): Answers {
  const r = demo.requirements
  return {
    company: '',
    kind: 'company',
    use_case: '',
    sells_to_us_federal: 'unsure',
    deploy_countries: [],
    uptime_critical: 'unsure',
    budget_usd: null,
    need_by_days: null,
    robot_name: demo.name.replace(/\s*\(.*\)\s*$/, ''),
    final_assembly_country: demo.final_assembly_country,
    mass_kg: r.mass_kg,
    wheel_radius_mm: Math.round(r.wheel_radius_m * 1e6) / 1e3,
    n_drive_motors: r.n_drive_motors,
    gear_ratio: r.gear_ratio,
    max_slope_deg: r.max_slope_deg,
    v_max_mps: r.v_max_mps,
    accel_mps2: r.accel_mps2,
    bus_voltage_v: r.bus_voltage_v,
    envelope_mm: r.envelope_mm,
    efficiency: r.efficiency,
    crr: r.crr,
    safety_factor: r.safety_factor,
    bom: [],
  }
}

export function toRobot(a: Answers): Robot {
  return {
    name: a.robot_name,
    final_assembly_country: a.final_assembly_country,
    requirements: {
      mass_kg: a.mass_kg,
      wheel_radius_m: a.wheel_radius_mm / 1000,
      n_drive_motors: a.n_drive_motors,
      gear_ratio: a.gear_ratio,
      efficiency: a.efficiency,
      crr: a.crr,
      max_slope_deg: a.max_slope_deg,
      accel_mps2: a.accel_mps2,
      v_max_mps: a.v_max_mps,
      bus_voltage_v: a.bus_voltage_v,
      envelope_mm: a.envelope_mm,
      safety_factor: a.safety_factor,
    },
    bom: a.bom,
  }
}

export interface CompanyFacts {
  name: string
  kind: Answers['kind']
  robot: string
  use_case: string
  facts: ProjectFacts
}

const yesNo = (v: YesNo): boolean | null => (v === 'unsure' ? null : v === 'yes')

/** The v4 ProjectFacts shape (docs/BUILD-PLAN-v4.md section 4). Stated by the user, not checked. */
export function toFacts(a: Answers): CompanyFacts {
  return {
    name: a.company,
    kind: a.kind,
    robot: a.robot_name,
    use_case: a.use_case,
    facts: {
      sells_to_us_federal: yesNo(a.sells_to_us_federal),
      deploy_countries: a.deploy_countries,
      uptime_critical: yesNo(a.uptime_critical),
      budget_usd: a.budget_usd,
      need_by_days: a.need_by_days,
    },
  }
}

/**
 * The answers that feed the torque and bus voltage written into the agent's goal
 * (backend: engineering/spec_checks.py `requirement`, agents/targets.py `goal_for`). Recordings
 * are keyed by that goal, so changing any of these means real agent runs. Top speed and the
 * envelope are only used by the checks.
 */
export const LIVE_FIELDS = [
  'mass_kg',
  'wheel_radius_mm',
  'n_drive_motors',
  'gear_ratio',
  'efficiency',
  'crr',
  'max_slope_deg',
  'accel_mps2',
  'safety_factor',
  'bus_voltage_v',
] as const satisfies readonly (keyof Answers)[]

export function needsLiveAgents(a: Answers, demo: Robot): boolean {
  const base = defaultAnswers(demo)
  return LIVE_FIELDS.some((f) => a[f] !== base[f])
}

/** True when a job on these answers gives the same compliance card and checks as the demo robot
 * (the name does not matter), so the demo-robot panels are still correct. */
export function matchesDemo(a: Answers, demo: Robot): boolean {
  const mine = toRobot(a)
  return (
    mine.final_assembly_country === demo.final_assembly_country &&
    JSON.stringify(mine.requirements) === JSON.stringify(demo.requirements) &&
    JSON.stringify(mine.bom) === JSON.stringify(demo.bom)
  )
}

const KEY = 'onboarding-v1'

/** What the browser remembers: `answers: null` means the user skipped to the demo robot. */
export interface Saved {
  answers: Answers | null
}

export function loadSaved(storage: Pick<Storage, 'getItem'> = localStorage): Saved | null {
  try {
    const raw = storage.getItem(KEY)
    if (!raw) return null
    const saved = JSON.parse(raw) as Saved
    if (saved.answers === null) return saved
    return Array.isArray(saved.answers?.bom) && typeof saved.answers.mass_kg === 'number' ? saved : null
  } catch {
    return null // storage blocked or the entry is not ours: ask again
  }
}

export function saveAnswers(answers: Answers | null, storage: Pick<Storage, 'setItem'> = localStorage) {
  try {
    storage.setItem(KEY, JSON.stringify({ answers } satisfies Saved))
  } catch {
    // storage blocked: the answers last for this page load only
  }
}
