    help: 'A CSV with one part per line: part, category, qty, unit_cost_usd, origin.',
  },
]

/** Kept at the demo values unless changed in the review screen's Advanced block. */
export const ADVANCED = [
  { id: 'efficiency', label: 'Drivetrain efficiency (0 to 1)', max: 1 },
  { id: 'crr', label: 'Rolling resistance coefficient', max: 1 },
  { id: 'safety_factor', label: 'Safety factor', max: null },
] as const satisfies readonly { id: keyof Answers; label: string; max: number | null }[]

export type Parsed<T> = { ok: true; value: T } | { ok: false; error: string }
const fail = (error: string): Parsed<never> => ({ ok: false, error })

export function parseNumber(
  raw: string,
  opts: { integer?: boolean; allowZero?: boolean; optional?: boolean; max?: number | null } = {},
): Parsed<number | null> {
  const text = raw.trim().replace(/^\$/, '').replaceAll(',', '')
  if (text === '') return opts.optional ? { ok: true, value: null } : fail('Please enter a number.')
  if (!/^\d+(\.\d+)?$/.test(text)) return fail('That is not a number.')
  const value = Number(text)
  if (opts.integer && !Number.isInteger(value)) return fail('Use a whole number.')
  if (value === 0 && !opts.allowZero) return fail('This has to be above 0.')
  if (opts.max != null && value > opts.max) return fail(`This cannot be above ${opts.max}.`)
  return { ok: true, value }
}

/** One ISO-2 country code, upper-cased. */
export function parseCountry(raw: string): Parsed<string> {
  const text = raw.trim()
  return /^[A-Za-z]{2}$/.test(text)
    ? { ok: true, value: text.toUpperCase() }
    : fail('Use a 2-letter country code, like DE or MX.')
}

/** Several ISO-2 codes separated by commas or spaces. Empty input gives an empty list. */
export function parseCountries(raw: string): Parsed<string[]> {
  const out: string[] = []
  for (const part of raw.split(/[\s,]+/).filter(Boolean)) {
    const one = parseCountry(part)
    if (!one.ok) return one
    if (!out.includes(one.value)) out.push(one.value)
  }
  return { ok: true, value: out }
}

/** How one answer reads on the review screen and the company card. */
export function display(q: Question, a: Answers): string {
  const v = a[q.id]
  if (q.kind === 'bom') return a.bom.length === 0 ? 'not uploaded' : `${a.bom.length} parts`
  if (v == null || v === '') return 'not given'
  if (q.kind === 'multi') {
    const list = v as string[]
    return list.length === 0 ? 'not given' : list.join(', ')
  }
  if (q.kind === 'choice') return q.options.find((o) => o.value === v)?.label ?? String(v)
  if (q.kind === 'number' && q.unit) return q.unit === ': 1' ? `${String(v)}:1` : `${String(v)} ${q.unit}`
  return String(v)
}
