import { useEffect, useState } from 'react'
import { needsLiveAgents, type Answers } from '../onboarding/answers'
import {
  ADVANCED,
  QUESTIONS,
  display,
  parseCountries,
  parseCountry,
  parseNumber,
  type Option,
  type Parsed,
  type Question,
} from '../onboarding/questions'
import type { Robot } from '../types'
import { BomUpload } from './BomUpload'

interface Props {
  demo: Robot
  initial: Answers
  onDone: (answers: Answers) => void
  /** Leave onboarding without answers and use the demo robot. */
  onSkip: () => void
}

const REVIEW = QUESTIONS.length
const LETTERS = 'ABCDEFGH'
const SECTIONS = [...new Set(QUESTIONS.map((q) => q.section))]

/** What the text box of a step starts with, and whether the "Other" box is open. */
function entering(q: Question | undefined, a: Answers): { draft: string; other: boolean } {
  if (!q) return { draft: '', other: false }
  const v = a[q.id]
  if (q.kind === 'text' || q.kind === 'number') return { draft: v == null ? '' : String(v), other: false }
  if (q.kind === 'choice') {
    const listed = q.options.some((o) => o.value === v)
    return { draft: listed ? '' : String(v), other: !listed }
  }
  if (q.kind === 'multi') {
    const extra = (v as string[]).filter((c) => !q.options.some((o) => o.value === c))
    return { draft: extra.join(', '), other: extra.length > 0 }
  }
  return { draft: '', other: false }
}

/** Typeform-style intake: one question on screen, Enter to go on, then a review screen. */
export function Onboarding({ demo, initial, onDone, onSkip }: Props) {
  const [answers, setAnswers] = useState(initial)
  const [index, setIndex] = useState(0)
  const [step, setStep] = useState(() => entering(QUESTIONS[0], initial))
  const [error, setError] = useState<string | null>(null)
  const [back, setBack] = useState(false)
  const [advanced, setAdvanced] = useState(() =>
    Object.fromEntries(ADVANCED.map((f) => [f.id, String(initial[f.id])])),
  )

  const q: Question | undefined = QUESTIONS[index]
  const set = (id: keyof Answers, value: Answers[keyof Answers], from: Answers = answers): Answers => {
    const next = { ...from, [id]: value }
    setAnswers(next)
    return next
  }
  const go = (to: number, from: Answers = answers) => {
    setBack(to < index)
    setIndex(to)
    setStep(entering(QUESTIONS[to], from))
    setError(null)
  }
  const reject = (r: Parsed<unknown>) => {
    if (!r.ok) setError(r.error)
    return !r.ok
  }

  const parseOther = (kind: 'country' | 'positive'): Parsed<string | number | null> =>
    kind === 'country' ? parseCountry(step.draft) : parseNumber(step.draft)

  /** Check the current step, store its answer and move on. */
  const next = () => {
    if (!q) return finish()
    if (q.kind === 'text') {
      const text = step.draft.trim()
      if (!text) return setError('Please type an answer.')
      return go(index + 1, set(q.id, text))
    }
    if (q.kind === 'number') {
      const r = parseNumber(step.draft, q)
      if (reject(r) || !r.ok) return
      return go(index + 1, set(q.id, r.value))
    }
    if (q.kind === 'choice') {
      if (!step.other) return go(index + 1)
      const r = parseOther(q.other ?? 'country')
      if (reject(r) || !r.ok) return
      return go(index + 1, set(q.id, r.value))
    }
    if (q.kind === 'multi') {
      const picked = (answers[q.id] as string[]).filter((c) => q.options.some((o) => o.value === c))
      const r = step.other ? parseCountries(step.draft) : ({ ok: true, value: [] } as Parsed<string[]>)
      if (reject(r) || !r.ok) return
      const all = [...picked, ...r.value.filter((c) => !picked.includes(c))]
      if (all.length === 0) return setError('Pick at least one.')
      return go(index + 1, set(q.id, all))
    }
    if (answers.bom.length === 0) return setError('Upload a CSV, or use the sample BOM.')
    go(index + 1)
  }

  const pick = (o: Option) => {
    if (!q) return
    if (q.kind === 'choice') return go(index + 1, set(q.id, o.value))
    if (q.kind === 'multi') {
      const now = answers[q.id] as string[]
      const value = String(o.value)
      set(q.id, now.includes(value) ? now.filter((c) => c !== value) : [...now, value])
      setError(null)
    }
  }
  const openOther = () => {
    setStep((s) => ({ ...s, other: q?.kind === 'multi' ? !s.other : true }))
    setError(null)
  }

  const finish = () => {
    let done = answers
    for (const f of ADVANCED) {
      const r = parseNumber(advanced[f.id], { max: f.max })
      if (!r.ok) return setError(`${f.label}: ${r.error}`)
      done = { ...done, [f.id]: r.value }
    }
    const missing = QUESTIONS.findIndex((x) => x.kind === 'text' && !String(done[x.id]).trim())
    if (missing >= 0) return go(missing)
    if (done.bom.length === 0) return go(QUESTIONS.findIndex((x) => x.kind === 'bom'))
    onDone(done)
  }

  // Keyboard: Enter goes on, Shift+Enter goes back, letters pick a choice. Re-bound every render
  // so the handler always sees the current step.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement
      const typing = el.tagName === 'INPUT' && (el as HTMLInputElement).type !== 'file'
      if (e.key === 'Enter') {
        // Buttons, links and <summary> act on Enter themselves.
        if (!typing && ['BUTTON', 'A', 'SUMMARY', 'LABEL'].includes(el.tagName)) return
        e.preventDefault()
        if (e.shiftKey) index > 0 && go(index - 1)
        else next()
        return
      }
      if (typing || e.metaKey || e.ctrlKey || e.altKey) return
      if (q && (q.kind === 'choice' || q.kind === 'multi')) {
        const n = LETTERS.indexOf(e.key.toUpperCase())
        if (n >= 0 && n < q.options.length) pick(q.options[n])
        else if (n === q.options.length && q.other) openOther()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  })

  const draftInput = (placeholder: string | undefined, numeric: boolean) => (
    <input
      className="ob-input"
      autoFocus
      value={step.draft}
      placeholder={placeholder}
      inputMode={numeric ? 'decimal' : 'text'}
      aria-label={q?.prompt}
      aria-invalid={error != null}
      onChange={(e) => {
        setStep({ ...step, draft: e.target.value })
        setError(null)
      }}
    />
  )

  const live = needsLiveAgents(
    { ...answers, ...Object.fromEntries(ADVANCED.map((f) => [f.id, Number(advanced[f.id])])) },
    demo,
  )

  return (
    <div className="ob">
      <div
        className="ob-progress"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={REVIEW}
        aria-valuenow={index}
        aria-label="Onboarding progress"
      >
        <div style={{ width: `${(index / REVIEW) * 100}%` }} />
      </div>

      <div className={`ob-step${back ? ' back' : ''}`} key={index}>
        {q ? (
          <>
            <p className="ob-count muted">
              {q.section} · question {index + 1} of {REVIEW}
            </p>
            <h1 className="ob-prompt">
              {q.prompt}
              {q.kind === 'number' && q.optional && <span className="muted"> (optional)</span>}
            </h1>
            {q.help && <p className="ob-help muted">{q.help}</p>}

            {q.kind === 'text' && draftInput(q.placeholder, false)}
            {q.kind === 'number' && (
              <div className="ob-unit">
                {draftInput(undefined, true)}
                {q.unit && <span className="muted">{q.unit}</span>}
              </div>
            )}
            {(q.kind === 'choice' || q.kind === 'multi') && (
              <div className="ob-options" role={q.kind === 'choice' ? 'radiogroup' : 'group'} aria-label={q.prompt}>
                {q.options.map((o, i) => {
                  const on =
                    q.kind === 'choice'
                      ? !step.other && answers[q.id] === o.value
                      : (answers[q.id] as string[]).includes(String(o.value))
                  return (
                    <button
                      key={o.value}
                      type="button"
                      role={q.kind === 'choice' ? 'radio' : 'checkbox'}
                      aria-checked={on}
                      className={`ob-option${on ? ' on' : ''}`}
                      onClick={() => pick(o)}
                    >
                      <kbd>{LETTERS[i]}</kbd> {o.label}
                    </button>
                  )
                })}
                {q.other && (
                  <button
                    type="button"
                    role={q.kind === 'choice' ? 'radio' : 'checkbox'}
                    aria-checked={step.other}
                    className={`ob-option${step.other ? ' on' : ''}`}
                    onClick={openOther}
                  >
                    <kbd>{LETTERS[q.options.length]}</kbd> Other
                  </button>
                )}
                {q.other && step.other && (
                  <div className="ob-unit">
                    {draftInput(
                      q.other === 'positive' ? undefined : q.kind === 'multi' ? 'DE, MX' : 'DE',
                      q.other === 'positive',
                    )}
                    <span className="muted">
                      {q.other === 'positive' ? 'V' : q.kind === 'multi' ? '2-letter codes' : '2-letter code'}
                    </span>
                  </div>
                )}
              </div>
            )}
            {q.kind === 'bom' && (
              <BomUpload
                rows={answers.bom}
                sample={demo.bom}
                onChange={(rows) => {
                  set('bom', rows)
                  setError(null)
                }}
              />
            )}
          </>
        ) : (
          <>
            <p className="ob-count muted">Review</p>
            <h1 className="ob-prompt">Does this look right?</h1>
            <p className="ob-help muted">Pick any line to change it.</p>
            {SECTIONS.map((section) => (
              <div key={section} className="ob-review">
                <h2>{section}</h2>
                {QUESTIONS.map((x, i) =>
                  x.section === section ? (
                    <button key={x.id} type="button" className="ob-review-row" onClick={() => go(i)}>
                      <span className="muted">{x.label}</span>
                      <strong>{display(x, answers)}</strong>
                    </button>
                  ) : null,
                )}
              </div>
            ))}
            <details className="ob-advanced">
              <summary>Advanced drivetrain values</summary>
              {ADVANCED.map((f) => (
                <label key={f.id}>
                  <span className="muted">{f.label}</span>
                  <input
                    className="ob-input"
                    inputMode="decimal"
                    value={advanced[f.id]}
                    onChange={(e) => {
                      setAdvanced({ ...advanced, [f.id]: e.target.value })
                      setError(null)
                    }}
                  />
                </label>
              ))}
            </details>
            {live && (
              <p className="ob-live">
                Your drivetrain differs from the recorded demo, so agents will run live (up to 8
                TinyFish agent runs, needs the live token).
              </p>
            )}
          </>
        )}

        {error && (
          <p className="error" role="alert">
            {error}
          </p>
        )}

        <div className="ob-nav">
          <button type="button" className="primary" onClick={next}>
            {q ? 'OK' : 'Find and Redesign'}
          </button>
          <span className="muted ob-hint">
            press <kbd>Enter</kbd>
          </span>
          {index > 0 && (
            <button type="button" className="secondary" onClick={() => go(index - 1)}>
              Back
            </button>
          )}
          {q?.kind === 'number' && q.optional && (
            <button type="button" className="ob-link" onClick={() => go(index + 1, set(q.id, null))}>
              Skip
            </button>
          )}
          {index === 0 && (
            <button type="button" className="ob-link" onClick={onSkip}>
              Skip, use the demo robot
            </button>
          )}
        </div>
      </div>
    </div>
  )
}
