      { part: 'Motor', category: 'motor', qty: 2, unit_cost_usd: '45.00', origin: 'CN', supply_risk: 'ndfeb_magnets' },
    ]
    expect(parseBomCsv(bomToCsv(rows))).toEqual({ rows, errors: [] })
  })
})
