            </p>
            {step === 'drivetrain' && found.length > 0 && (
              <p className="ob-help muted">
                From your files:{' '}
                {listOf(found.map((s) => `${s.label.toLowerCase()} ${s.value}${s.unit ? ` ${s.unit}` : ''}`))}.
